def requested_owner(owner: int = Query(...), current_user: User = Depends(get_current_user)) -> int:
    return owner

Owner = Annotated[int, Depends(requested_owner)]

@router.get("/a/{item_id}")
def a(item_id: int, session, current_user: CurrentUser, owner: Owner):
    statement = select(Item).where(Item.id == item_id, Item.owner_id == owner)
    item = session.exec(statement).first()
    if item is None:
        raise HTTPException(404)
    return item

@router.delete("/b/{item_id}")
def b(item_id: int, session, current_user: CurrentUser, owner: int = Depends(requested_owner)):
    item = session.get(Item, item_id)
    if item.owner_id != owner:
        raise HTTPException(403)
    session.delete(item)

